function heading(){return `<div class="page-heading"><div><h1>上午好，林老师 <span style="font-size:20px;color:#cba980;margin-left:5px">☀</span></h1><p>今天也从一个好问题开始。这里是你的教学工作空间。</p></div><span class="date-label">${icon('calendar')}10 月 27 日，星期二</span></div>`;}
function homeA(){return `${heading()}${hero()}${metrics()}<div class="dashboard-grid"><section><div class="section-heading"><h2>我的课程 <span>${courses.length}</span></h2><button class="text-btn" data-action="navigate" data-view="courses">查看全部 ${icon('arrow')}</button></div><div class="course-grid">${courses.slice(0,3).map(courseCard).join('')}</div><div class="quick-start">${icon('upload')}<div><strong>有新的教学资料？从这里开始。</strong><p>上传讲义或笔记，整理成下一节课的内容。</p></div><button class="text-btn" data-action="upload">上传资料 ${icon('arrow')}</button></div></section><aside class="dashboard-aside"><section><div class="section-heading"><h2>待办事项 <span>3</span></h2><span class="badge">需要你关注</span></div>${todos()}</section>${recent()}</aside></div><p class="bottom-note">${icon('shield')}好的教学，始于有据可依的每一步。　·　知行教师工作空间</p>`;}

function coursesPage(){const filtered=courses.filter(c=>(state.courseFilter==='all'||(state.courseFilter==='active'?c.status==='进行中':c.status==='备课中'))&&c.title.toLowerCase().includes(state.query.toLowerCase()));return `<div class="page-heading"><div><h1>我的课程</h1><p>每一门课，都有自己的生长节奏。</p></div>${btn('新建课程','new-course','primary','plus')}</div><div class="list-toolbar">${[['all','全部课程'],['active','进行中'],['draft','备课中']].map(([id,label])=>`<button class="filter-button ${state.courseFilter===id?'active':''}" data-action="course-filter" data-filter="${id}">${label}</button>`).join('')}<label class="search-input">${icon('search')}<input id="course-query" aria-label="搜索课程" placeholder="搜索课程名称" value="${esc(state.query)}"></label></div><div class="course-grid" id="course-results">${filtered.length?filtered.map(courseCard).join(''):'<div class="empty-state"><h3>没有找到课程</h3><p>换一个关键词，或新建一门课程。</p></div>'}</div><div class="quick-start">${icon('spark')}<div><strong>从现有讲义出发，开始一门新课。</strong><p>先上传资料，再逐步完善教学内容与练习。</p></div><button class="text-btn" data-action="upload">上传资料 ${icon('arrow')}</button></div>`;}
function sourcePane(){return `<aside class="outline-pane"><div class="pane-heading">课程目录<button class="icon-button" data-action="course-outline" aria-label="查看课程大纲">${icon('layers')}</button></div><div class="outline-course">${esc(course().title)}<br><span style="font-size:12px;color:#a5a5b4">2026 秋季学期 · ${course().chapters} 个章节</span></div>${chapterNames().map((name,i)=>`<button class="outline-item ${i===state.chapter?'selected':''}" data-action="chapter" data-index="${i}"><span class="chapter-number">${String(i+1).padStart(2,'0')}</span>${esc(name)}</button>`).join('')}<div class="source-heading">参考资料 <span>${sources.length}</span></div>${sources.map((f,i)=>`<button class="source-item ${i===0?'selected':''}" data-action="view-source" data-id="${f.id}"><span class="file-icon">${icon('file')}</span><span>${esc(f.name.length>16?f.name.slice(0,14)+'…':f.name)}<small>${esc(f.size)} · ${f.sample?'示例资料':'本地选择'}</small></span>${icon('check')}</button>`).join('')}<button class="upload-mini" data-action="upload">${icon('upload')}添加教学资料</button><p class="outline-foot">资料与教学内容关联，<br>随时可以追溯原始出处。</p></aside>`;}
function steps(){const step=state.published?4:state.tab==='questions'?(questions.length?3:2):state.tab==='concepts'?1:0;return `<nav class="steps" aria-label="备课进度">${['准备资料','整理知识点','设计练习','检查与发布'].map((name,i)=>`${i?'<span class="step-line"></span>':''}<button class="step ${i<step?'done':i===step?'active':''}" data-action="step" data-index="${i}"><span>${i<step?icon('check'):i+1}</span>${name}</button>`).join('')}</nav>`;}
function documentContent(){
 const pythonContent=`<p class="document-kicker">CHAPTER ${String(state.chapter+1).padStart(2,'0')}　/　LESSON NOTES</p><h2>${esc(selectedChapter())}</h2><p>程序如何根据不同情况做出选择？又如何把重复的工作交给计算机？这一章，我们从生活中的判断出发，理解程序的执行逻辑。</p><div class="learning-goal"><strong>本节学习目标</strong>能写出条件分支与循环，解释每一步的执行过程，并留意边界情况。</div><h3>01　让程序做出选择</h3><p>条件语句让程序根据表达式的真假，决定接下来执行哪一段代码。<strong>写条件时，要特别留意等于的情况。</strong></p><pre class="code-block"><span class="code-purple">score</span> = <span class="code-blue">60</span>\n<span class="code-purple">if</span> score &gt;= <span class="code-blue">60</span>:\n    <span class="code-blue">print</span>(<span class="code-purple">"通过，继续下一步"</span>)\n<span class="code-purple">else</span>:\n    <span class="code-blue">print</span>(<span class="code-purple">"再巩固一下"</span>)</pre><h3>02　把重复交给循环</h3><p>当操作需要重复执行，可以使用 <strong>for</strong> 或 <strong>while</strong>。先明确循环的起点、结束条件，以及每一轮发生的变化。</p><ul><li><strong>for</strong>：依次遍历序列中的元素。</li><li><strong>range()</strong>：从起点开始，到终点之前结束。</li><li><strong>break / continue</strong>：控制整个循环或当前迭代。</li></ul><h3>想一想</h3><p>如果把上面代码中的 <strong>&gt;=</strong> 改成 <strong>&gt;</strong>，当分数恰好为 60 时，结果会发生什么变化？</p>`;
 const genericContent=`<p class="document-kicker">CHAPTER ${String(state.chapter+1).padStart(2,'0')}　/　LESSON NOTES</p><h2>${esc(selectedChapter())}</h2><p>这一节从一个具体的问题开始，逐步建立对${esc(selectedChapter())}的理解。先说清楚问题，再观察方法，最后通过练习检查理解。</p><div class="learning-goal"><strong>本节学习目标</strong>理解核心概念，能够用自己的语言解释，并将方法应用到新的例子中。</div><h3>01　从问题出发</h3><p>${state.course==='data'?'当数据的组织方式发生变化，查找、插入和删除的效率也会改变。选择合适的数据结构，是解决问题的第一步。':'机器学习通过数据中的例子建立模型。训练之前，需要先明确输入、目标与评价标准。'}</p><h3>02　建立概念之间的联系</h3><p>用具体的例子观察变化，把每一步的输入和输出写下来。比较不同方法的适用条件，并讨论边界情况。</p><div class="learning-goal"><strong>课堂讨论</strong>如果问题的规模扩大十倍，你会保留现在的方法，还是做出调整？说说你的依据。</div><h3>03　通过练习检查理解</h3><p>请在右侧让知行协助设计练习。生成结果以本课程的演示内容呈现，教师可以在发布前修改。</p>`;
 return `<div class="document-toolbar"><span class="flex">${icon('file')}${esc(sources[0]?.name||'课程教学笔记')}　·　${state.course==='python'?'第 3—18 页':'示例章节'}</span><button class="text-btn" data-action="edit-document" style="font-size:12px">${icon('edit')}编辑内容</button></div><article class="document-body">${state.sourceBusy?'<div class="loading-banner">正在演示资料整理…</div>':''}${state.customDocument?`<p class="document-kicker">LESSON NOTES / 已修改</p><h2>${esc(selectedChapter())}</h2><div style="white-space:pre-wrap">${esc(state.customDocument)}</div>`:state.course==='python'&&state.chapter===2?pythonContent:genericContent}</article><footer class="doc-footer"><span>${icon('shield')} 内容可编辑 · 发布前请检查</span><button class="text-btn" data-action="tab" data-tab="concepts">检查知识点 ${icon('arrow')}</button></footer>`;
}
function conceptContent(){return `<div class="document-toolbar"><span class="flex">${icon('target')}本节教学目标与知识点</span>${badge(`${concepts.length} 个知识点`,'blue')}</div><div class="document-body"><p class="document-kicker">LEARNING OBJECTIVES</p><h2>让教学目标，更清晰。</h2><p>从讲义中整理出的知识点。你可以直接修改学习目标，练习将围绕这些内容设计。</p>${concepts.map((c,i)=>`<article class="concept-card"><div class="concept-top"><h3>${String(i+1).padStart(2,'0')}　${esc(c.title)}</h3>${badge('可编辑')}</div><p>学生学完后，应该能够：</p><textarea data-concept="${c.id}" aria-label="${esc(c.title)}学习目标">${esc(c.goal)}</textarea><span class="concept-source">${icon('link')}${esc(c.source)} · 示例出处</span></article>`).join('')}<div class="flex spread"><span style="font-size:12px;color:#acb0c1">修改会保留在当前原型中</span>${btn('根据知识点设计练习','generate','primary small','spark')}</div></div>`;}
function questionContent(){return `<div class="document-toolbar"><span class="flex">${icon('checkSquare')}练习设计</span>${questions.length?badge(state.published?'已发布':'草稿 · 待教师确认',state.published?'green':'amber'):badge('尚未生成')}</div><div class="document-body">${state.generateBusy?`<div class="empty-state"><div class="empty-icon">${icon('spark')}</div><h3>正在准备练习草稿</h3><p>围绕教学目标组织题目，生成后请检查题干、答案和解析。</p><div class="typing" style="justify-content:center"><i></i><i></i><i></i></div></div>`:!questions.length?`<div class="empty-state"><div class="empty-icon">${icon('checkSquare')}</div><h3>把理解，变成一道好题。</h3><p>根据本节知识点生成一组练习，再由你检查和调整。这里先用 3 道示例题体验流程。</p>${btn('生成练习草稿','generate','primary','spark')}<p style="font-size:12px;margin-top:16px">纯前端演示 · 不调用模型</p></div>`:`<div class="subtle-row"><span>已选 <strong>${questions.filter(q=>q.selected).length}</strong> / ${questions.length} 道题</span><button class="text-btn" style="font-size:12px" data-action="generate">${icon('refresh')}重新生成</button></div>${questions.map(q=>`<article class="question-card"><header class="question-card-header"><label><input type="checkbox" data-question-select="${q.id}" aria-label="选入第 ${q.id} 题" ${q.selected?'checked':''}>第 ${q.id} 题</label>${badge(q.type)}${badge(q.difficulty,q.difficulty==='基础'?'blue':'purple')}<button class="icon-button" data-action="edit-question" data-id="${q.id}" aria-label="修改第 ${q.id} 题">${icon('edit')}</button></header><div class="question-content">${state.questionEditing===q.id?`<label class="inline-label" for="question-title-${q.id}">题目内容</label><textarea class="question-edit" id="question-title-${q.id}">${esc(q.title)}</textarea><div class="flex" style="justify-content:flex-end;margin-top:9px">${btn('取消','cancel-edit','small')}${btn('保存修改','save-question','primary small','','data-id="'+q.id+'"')}</div>`:`<p class="question-title">${esc(q.title)}</p>${q.code?`<pre class="code-block">${esc(q.code)}</pre>`:''}${q.options.length?`<div class="question-options">${q.options.map((o,i)=>`<div class="question-option ${i===q.correct?'correct':''}">${String.fromCharCode(65+i)}. ${esc(o)} ${i===q.correct?'✓':''}</div>`).join('')}</div>`:'<div class="answer-box" style="font-size:12px;padding:10px">学生将通过文字作答</div>'}<details><summary>参考解析与知识点</summary><p>${esc(q.explanation)}</p><p>知识点：${esc(q.concept)}</p></details>`}</div></article>`).join('')}<div class="alert-note">${icon('shield')} 这些是演示练习草稿。真实使用时，需要核对资料出处、答案与难度后再发布。</div><div class="flex" style="justify-content:flex-end;margin-top:19px">${btn('学生视角预览','preview','small','eye')}${btn(state.published?'查看发布详情':'检查并发布','publish','primary small','arrow')}</div>`}</div>`;}
function assistant(){return `<aside class="assistant-pane ${state.aiOpen?'open':''}" aria-label="知行备课助手"><div class="assistant-header"><span class="assistant-logo">${icon('spark')}</span>知行 · 备课助手 ${badge('演示','blue')}<button class="icon-button ai-toggle" data-action="ai-toggle" aria-label="关闭备课助手" style="width:22px;height:22px">${icon('close')}</button></div><div class="assistant-context">${icon('link')}正在参考：${esc(selectedChapter())}<details><summary>查看参考范围 · ${Number(state.contextSource)+Number(state.contextConcept)} 项</summary><label><input type="checkbox" data-context="contextSource" ${state.contextSource?'checked':''}>本章教学资料</label><label><input type="checkbox" data-context="contextConcept" ${state.contextConcept?'checked':''}>学习目标与知识点</label></details></div><div class="assistant-messages" id="ai-messages"><div class="assistant-message"><strong>从这节课开始，一起备课。</strong><p>我已经准备好本章的示例内容。你可以检查知识点、设计练习，也可以直接告诉我你的想法。</p><div class="assistant-options"><button data-action="extract">${icon('layers')}整理本章知识点 ${icon('arrow')}</button><button data-action="generate">${icon('checkSquare')}设计一组课堂练习 ${icon('arrow')}</button><button data-action="ai-prompt" data-prompt="帮我找出本章学生容易出错的地方">${icon('target')}看看学生容易卡在哪里 ${icon('arrow')}</button></div></div>${state.chat.map(m=>`<div class="assistant-message ${m.role==='user'?'user':''}">${m.role==='assistant'?'<strong>知行</strong>':''}<p>${esc(m.text).replace(/\n/g,'<br>')}</p>${m.action?`<button class="text-btn" data-action="${m.action}" ${m.tab?`data-tab="${m.tab}"`:''} style="font-size:12px;margin-top:9px">${esc(m.label)} ${icon('arrow')}</button>`:''}${m.role==='assistant'?'<p class="message-note">示例回答 · 未调用真实模型</p>':''}</div>`).join('')}${state.aiBusy?'<div class="typing" role="status" aria-label="正在生成演示回答"><i></i><i></i><i></i></div>':''}</div><form id="ai-form" class="assistant-compose"><textarea id="ai-input" aria-label="向备课助手提问" placeholder="例如：帮我设计一道关于边界值的题…" rows="2">${esc(state.aiDraft||'')}</textarea><div class="compose-foot"><span>Enter 发送 · Shift + Enter 换行</span><button class="send-button" type="submit" aria-label="发送给备课助手" ${state.aiBusy?'disabled':''}>${icon('arrow')}</button></div></form><p class="assistant-disclaimer">AI 辅助设计，教学内容由你确认。</p></aside>`;}
function studio(){return `<div class="studio-heading"><div><div class="flex" style="gap:8px"><h1>第 ${state.chapter+1} 章 · ${esc(selectedChapter())}</h1>${badge(state.published?'已发布':'备课中',state.published?'green':'blue')}</div><p>${esc(course().title)}　/　${courseClass()}　·　教学内容与练习</p></div><div class="studio-actions"><span class="saved-label">${icon('check')}当前页面已保留</span>${btn('AI 助手','ai-toggle','ai-toggle small','spark')}${btn('预览','preview','small preview-action','eye')}${btn(state.published?'发布详情':'检查与发布','publish','primary small','arrow')}</div></div>${steps()}<div class="studio-grid">${sourcePane()}<section class="document-pane"><nav class="document-tabs" aria-label="教学内容类型">${[['content','教学内容',''],['concepts','知识点',concepts.length],['questions','练习题',questions.length]].map(([id,name,num])=>`<button data-action="tab" data-tab="${id}" class="${state.tab===id?'active':''}" ${state.tab===id?'aria-current="page"':''}>${name}${num?`<small>${num}</small>`:''}</button>`).join('')}<button class="icon-button" data-action="document-options" aria-label="内容操作">${icon('more')}</button></nav>${state.tab==='content'?documentContent():state.tab==='concepts'?conceptContent():questionContent()}</section>${assistant()}</div>`;}
function assignmentsPage(){const rows=[...publishedHomeworks,{title:'第 3 章 · 条件判断与循环',course:'Python 程序设计 · Python 01 班',submitted:36,total:48,status:'待批改',color:'amber',due:'10 月 30 日 23:59'},{title:'第 2 章 · 栈与队列',course:'数据结构与算法 · 数据结构 01 班',submitted:36,total:42,status:'进行中',color:'blue',due:'10 月 29 日 23:59'},{title:'第 2 章 · 变量与数据类型',course:'Python 程序设计 · Python 01 班',submitted:48,total:48,status:'已完成',color:'green',due:'10 月 23 日 23:59'}].filter(r=>state.filter==='all'||(state.filter==='pending'?r.status==='待批改':r.status==='进行中'));return `<div class="page-heading"><div><h1>作业与批改</h1><p>从一份作答，看到学生的理解过程。</p></div>${btn('布置新作业','open-course','primary','plus','data-course="python" data-tab="questions"')}</div><div class="list-toolbar">${[['all','全部作业'],['pending','待批改'],['active','进行中']].map(([id,label])=>`<button class="filter-button ${state.filter===id?'active':''}" data-action="assignment-filter" data-filter="${id}">${label}</button>`).join('')}</div><div class="table-card"><table class="data-table"><thead><tr><th>作业名称</th><th>状态</th><th>提交情况</th><th>截止时间</th><th>操作</th></tr></thead><tbody>${rows.map((r,i)=>`<tr><td><span class="table-title">${esc(r.title)}</span><small>${esc(r.course)}</small></td><td>${badge(r.status,r.color,true)}</td><td>${r.total?`${r.submitted} <span class="muted">/ ${r.total} 人</span>`:'尚无提交 · 演示'}</td><td>${esc(r.due)}</td><td><button class="text-btn" data-action="review" data-index="0">${r.status==='已完成'?'查看作答':'查看与批改'} ${icon('arrow')}</button></td></tr>`).join('')}</tbody></table></div><div class="section-heading" style="margin-top:32px"><h2>值得重点关注的作答</h2><span class="muted" style="font-size:13px">${state.reviewed.length} 份已处理 · 示例数据</span></div>${reviewPanel()}`;}
function reviewPanel(){const r=demoSubmissions[state.review];return `<section class="review-layout"><aside class="review-queue"><h3>作答队列</h3>${demoSubmissions.map((r,i)=>`<button class="review-item ${i===state.review?'active':''}" data-action="review" data-index="${i}"><strong>${r.name}</strong><p>${r.item}</p>${badge(state.reviewed.includes(i)?'已复核':r.requested?'申请教师复核':'待关注',state.reviewed.includes(i)?'green':r.requested?'amber':'blue')}</button>`).join('')}</aside><article class="review-main"><div class="flex spread"><h2>${r.name}的作答</h2>${badge('保留原始作答')}</div><p>${r.item}　·　提交于今天 10:18</p><h3>学生答案与解释</h3><div class="answer-box">${esc(r.answer)}</div><h3>需要关注的地方</h3><div class="learning-goal" style="margin-top:0">${esc(r.reason)}<p style="font-size:12px;color:#aaaec0">演示建议，仅供教师复核时参考。</p></div><h3>教师复核</h3><label class="form-field"><span>复核结论</span><select id="review-verdict">${[['uncertain','暂不能确认'],['supported','解释有依据'],['contradiction','解释有矛盾']].map(([value,label])=>`<option value="${value}" ${(r.verdict||'uncertain')===value?'selected':''}>${label}</option>`).join('')}</select></label><label class="form-field"><span>复核依据（必填）</span><textarea id="review-notes" placeholder="结合题目、参考量规与学生原句，说明判断依据…">${esc(r.notes||'')}</textarea></label><h3><label for="review-feedback">给学生的反馈</label></h3><textarea id="review-feedback" placeholder="告诉学生哪里值得肯定，以及接下来可以怎样改进…">${esc(r.feedback||'')}</textarea><div class="review-foot">${btn('暂时跳过','next-review','','arrow')}${btn(state.reviewed.includes(state.review)?'更新反馈':'保存反馈并完成复核','save-review','primary','check')}</div>${state.reviewed.includes(state.review)?'<p class="completion-line">已保存本次演示反馈。</p>':''}</article></section>`;}
function resourcesPage(){const filtered=sources.filter(f=>f.name.toLowerCase().includes(state.resourceQuery.toLowerCase()));return `<div class="page-heading"><div><h1>资料库</h1><p>让每一份资料，都能成为下一节课的起点。</p></div>${btn('添加教学资料','upload','primary','upload')}</div><div class="list-toolbar"><span style="font-size:14px;color:#969bad">全部资料 · ${sources.length}</span><label class="search-input">${icon('search')}<input id="resource-query" aria-label="搜索资料" placeholder="搜索资料名称" value="${esc(state.resourceQuery)}"></label></div><div class="resource-grid" id="resource-results">${filtered.map(resourceCard).join('')}</div>`;}
function resourceCard(f){return `<article class="resource-card"><span class="file-icon">${icon('file')}</span><h3>${esc(f.name)}</h3><p>${esc(f.type)}　·　${esc(f.size)}<br>已关联：${esc(course().title)}<br>${f.sample?'示例资料，可体验阅读与备课流程':'本地文件仅在当前浏览器会话中使用'}</p><div class="flex spread">${badge(f.sample?'已整理':'已选择',f.sample?'blue':'amber')}<button class="text-btn" data-action="view-source" data-id="${f.id}" style="font-size:13px">查看资料 ${icon('arrow')}</button></div></article>`;}
function classesPage(){return `<div class="page-heading"><div><h1>教学班级</h1><p>把课程、作业和学生的学习过程连接起来。</p></div>${btn('新建教学班','new-class','primary','plus')}</div><div class="class-grid">${[{name:'Python 01 班',course:'Python 程序设计',count:48,complete:36,invite:'ZX-PY26',color:'blue'},{name:'数据结构 01 班',course:'数据结构与算法',count:42,complete:36,invite:'ZX-DS26',color:'amber'},...(state.customClass?[{name:state.customClass,course:courses.find(c=>c.id===state.customClassCourse)?.title||course().title,count:0,complete:0,invite:'ZX-NEW1',color:'purple'}]:[])].map((c,i)=>`<article class="class-card">${badge('2026 秋季学期',c.color)}<h2>${esc(c.name)}</h2><p>${esc(c.course)} · 林老师</p><div class="class-stats"><div><strong>${c.count}</strong><small>班级学生</small></div><div><strong>${c.complete}</strong><small>已完成本周作业</small></div><div><strong>${c.count?Math.round(c.complete/c.count*100):0}<span style="font-size:15px">%</span></strong><small>作业完成率</small></div></div><div class="class-card-foot"><span>班级邀请码：${c.invite}</span><button class="text-btn" data-action="copy-invite" data-invite="${c.invite}" style="font-size:13px">${icon('copy')}复制邀请</button></div><div style="margin-top:15px">${btn('查看本班作业','navigate','small','','data-view="assignments"')}</div></article>`).join('')}</div>`;}

function render(){const body=state.view==='home'?homeA():state.view==='studio'?studio():state.view==='courses'?coursesPage():state.view==='assignments'?assignmentsPage():state.view==='resources'?resourcesPage():classesPage();app.innerHTML=shell(`<div class="page ${state.view==='studio'?'studio-page':''}">${body}</div>`);document.title=`${viewNames[state.view]} · 知行`;bindInputs();syncMobileNavigation();const messages=document.querySelector('#ai-messages');if(messages&&state.chat.length)messages.scrollTop=messages.scrollHeight;}
function navigate(view){state.view=view;closeDialog();render();window.scrollTo({top:0,behavior:'instant'});history.replaceState(null,'',`${location.pathname}${location.search}#${view}`);}
function openCourse(id,tab){if(state.course!==id){keepCourseDraft();clearTimeout(aiTimer);clearTimeout(generateTimer);clearTimeout(sourceTimer);state.aiBusy=false;state.generateBusy=false;state.sourceBusy=false;state.aiDraft='';state.course=id;const saved=courseDrafts.get(id);if(saved){Object.assign(state,{chapter:saved.chapter,tab:saved.tab,customDocument:saved.customDocument,chat:saved.chat,published:saved.published,assignmentTitle:saved.assignmentTitle,publishClass:saved.publishClass,publishDue:saved.publishDue});questions=saved.questions;concepts=saved.concepts;sources=saved.sources;}else{state.customDocument='';state.chapter=Math.min(2,chapterNames().length-1);questions=[];state.published=false;state.chat=[];concepts=id==='python'?structuredClone(defaultPythonConcepts):genericConcepts();sources=id==='python'?structuredClone(defaultPythonSources):id==='data'?[{id:3,name:'栈与队列_课程笔记.pdf',type:'PDF',size:'1.8 MB',pages:'12 页',sample:true}]:id==='ai'?[{id:4,name:'监督学习_课程导读.md',type:'Markdown',size:'18 KB',pages:'课程笔记',sample:true}]:[];state.assignmentTitle=`第 ${state.chapter+1} 章 · ${selectedChapter()}`;}}state.tab=tab||'content';navigate('studio');}
function toast(message){const el=document.querySelector('#toast');el.textContent=message;el.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.classList.remove('show'),3200);}
function saveInputs(){document.querySelectorAll('[data-concept]').forEach(el=>{const c=concepts.find(c=>c.id===Number(el.dataset.concept));if(c)c.goal=el.value;});const ai=document.querySelector('#ai-input');if(ai)state.aiDraft=ai.value;const feedback=document.querySelector('#review-feedback');if(feedback){demoSubmissions[state.review].feedback=feedback.value;demoSubmissions[state.review].notes=document.querySelector('#review-notes')?.value||'';demoSubmissions[state.review].verdict=document.querySelector('#review-verdict')?.value||'uncertain';}}
function bindInputs(){document.querySelector('#ai-form')?.addEventListener('submit',e=>{e.preventDefault();sendAI();});document.querySelector('#ai-input')?.addEventListener('keydown',e=>{if(e.key==='Enter'&&!e.shiftKey&&!e.isComposing){e.preventDefault();sendAI();}});document.querySelector('#ai-input')?.addEventListener('input',e=>state.aiDraft=e.target.value);document.querySelectorAll('[data-concept]').forEach(el=>el.addEventListener('input',()=>{const c=concepts.find(c=>c.id===Number(el.dataset.concept));if(c)c.goal=el.value;}));document.querySelectorAll('[data-question-select]').forEach(el=>el.addEventListener('change',()=>{questions.find(q=>q.id===Number(el.dataset.questionSelect)).selected=el.checked;render();}));document.querySelectorAll('[data-context]').forEach(el=>el.addEventListener('change',()=>{state[el.dataset.context]=el.checked;}));document.querySelector('#review-feedback')?.addEventListener('input',e=>demoSubmissions[state.review].feedback=e.target.value);document.querySelector('#course-query')?.addEventListener('input',e=>{state.query=e.target.value;const filtered=courses.filter(c=>(state.courseFilter==='all'||(state.courseFilter==='active'?c.status==='进行中':c.status==='备课中'))&&c.title.toLowerCase().includes(state.query.toLowerCase()));document.querySelector('#course-results').innerHTML=filtered.map(courseCard).join('')||'<p class="muted" style="padding:25px">没有找到匹配的课程。</p>';});document.querySelector('#resource-query')?.addEventListener('input',e=>{state.resourceQuery=e.target.value;document.querySelector('#resource-results').innerHTML=sources.filter(f=>f.name.toLowerCase().includes(state.resourceQuery.toLowerCase())).map(resourceCard).join('')||'<p class="muted" style="padding:25px">没有找到匹配的资料。</p>';});}
function generate(){if(state.generateBusy)return;saveInputs();state.tab='questions';state.generateBusy=true;if(state.view!=='studio')state.view='studio';render();clearTimeout(generateTimer);generateTimer=setTimeout(()=>{questions=sampleQuestions();if(state.course!=='python'||state.chapter!==2){questions=[{id:1,type:'单选题',difficulty:'基础',concept:selectedChapter(),title:`学习“${selectedChapter()}”时，以下哪种学习方式最有助于检查理解？`,options:['只记住术语','用具体例子解释方法并检查边界','跳过练习','只阅读结论'],correct:1,explanation:'通过具体例子解释方法，并分析适用条件和边界，能帮助发现理解中的空缺。此题仅作流程演示。',selected:true},{id:2,type:'简答题',difficulty:'进阶',concept:selectedChapter(),title:`请举一个“${selectedChapter()}”的应用例子，说明它解决了什么问题，以及有哪些限制。`,options:[],correct:0,explanation:'教师可以结合本节教学目标，检查例子是否准确、步骤是否完整，以及是否识别适用边界。',selected:true}];}state.generateBusy=false;state.published=false;state.chat.push({role:'assistant',text:`练习草稿已经准备好：${questions.length} 道题。你可以修改题目、展开参考解析，或取消选入不需要的题目。`,action:'preview',label:'看看学生视角'});render();toast('演示练习已生成，请检查题干、答案与解析。');},950);}
function sendAI(prompt){if(state.aiBusy)return;const text=(prompt??document.querySelector('#ai-input')?.value??'').trim();if(!text)return;if(!state.contextSource&&!state.contextConcept){toast('请先选择至少一项参考内容。');return;}state.aiDraft='';state.chat.push({role:'user',text});state.aiBusy=true;state.aiOpen=true;render();clearTimeout(aiTimer);aiTimer=setTimeout(()=>{const response=/误区|出错|卡|边界/.test(text)?{text:'这节课可以重点检查三个地方：\n1. 把 > 和 >= 混淆，漏掉恰好等于的情况。\n2. 认为 range() 会包含终点。\n3. 混淆 break 与 continue 的作用。\n建议先让学生预测输出，再解释每一步的判断依据。',action:'generate',label:'围绕这些误区设计练习'}:/练习|题目|出题/.test(text)?{text:'可以把练习分成“预测输出 → 解释原因 → 换一个情境”三个层次。先用一道边界值题检查判断，再用 range() 题检查循环范围，最后让学生解释两种循环控制语句的区别。',action:'generate',label:'生成这组演示练习'}:/知识|目标|整理/.test(text)?{text:'本节可以围绕条件分支、循环范围、循环控制三个知识点组织教学。每个知识点都配一个可观察的学习目标，方便后面检查学生的理解。',action:'tab',tab:'concepts',label:'查看并修改知识点'}:{text:'可以先让学生预测程序会怎样运行，再逐行解释条件和变量的变化。对同一个例子改变一个边界值，观察输出是否改变。\n右侧建议用于讨论交互效果；这版没有连接真实模型。',action:'tab',tab:'concepts',label:'从本节知识点继续'};state.chat.push({role:'assistant',...response});state.aiBusy=false;render();},850);}

let lastFocus=null;
function closeDialog(){const d=overlay.querySelector('dialog');if(d?.open)d.close();overlay.replaceChildren();if(lastFocus?.isConnected)lastFocus.focus();}
function dialog(title,subtitle,body,footer='',onReady){lastFocus=document.activeElement;overlay.innerHTML=`<dialog aria-labelledby="dialog-title"><header class="dialog-header"><div><h2 id="dialog-title">${title}</h2>${subtitle?`<p>${subtitle}</p>`:''}</div><button class="icon-button" data-action="close-dialog" aria-label="关闭对话框">${icon('close')}</button></header><div class="dialog-body">${body}</div>${footer?`<footer class="dialog-footer">${footer}</footer>`:''}</dialog>`;const d=overlay.querySelector('dialog');d.addEventListener('cancel',e=>{e.preventDefault();closeDialog();});d.addEventListener('click',e=>{if(e.target===d){const rect=d.getBoundingClientRect();if(e.clientX<rect.left||e.clientX>rect.right||e.clientY<rect.top||e.clientY>rect.bottom)closeDialog();}});d.showModal();onReady?.(d);}
function uploadDialog(){let files=[];dialog('从一份资料，开始备课','选择课程并添加资料，体验整理内容的过程。',`<label class="form-field"><span>关联课程</span><select id="upload-course">${courses.map(c=>`<option value="${c.id}" ${c.id===state.course?'selected':''}>${esc(c.title)}</option>`).join('')}</select></label><label class="drop-zone" id="drop-zone">${icon('upload')}<strong>点击选择，或把文件拖到这里</strong><p>支持 PDF、Word、Markdown、TXT · 本原型不会上传文件</p><input id="upload-files" type="file" accept=".pdf,.docx,.doc,.md,.txt" multiple aria-label="选择教学资料"></label><div class="selected-files" id="selected-files"></div><div class="alert-note">${icon('spark')} PDF 和 Word 将使用示例内容演示整理结果；TXT 与 Markdown 可在浏览器本地读取，最多 1 MB。</div><p class="form-error" id="upload-error"></p>`, `<button class="text-btn" data-action="sample-upload">使用示例讲义</button>${btn('取消','close-dialog')}${btn('添加并整理','confirm-upload','primary','arrow')}`,d=>{const input=d.querySelector('#upload-files'),zone=d.querySelector('#drop-zone');const update=newFiles=>{files=Array.from(newFiles);d.querySelector('#selected-files').textContent=files.map(f=>`${f.name} · ${(f.size/1024).toFixed(1)} KB`).join(' / ');};input.addEventListener('change',()=>update(input.files));zone.addEventListener('dragover',e=>{e.preventDefault();zone.classList.add('dragging');});zone.addEventListener('dragleave',()=>zone.classList.remove('dragging'));zone.addEventListener('drop',e=>{e.preventDefault();zone.classList.remove('dragging');update(e.dataTransfer.files);});d.querySelector('[data-action="confirm-upload"]').addEventListener('click',async()=>{if(!files.length){d.querySelector('#upload-error').textContent='请先选择一份资料，或点击“使用示例讲义”。';return;}if(files.some(f=>!/^.+\.(pdf|docx?|md|txt)$/i.test(f.name))){d.querySelector('#upload-error').textContent='请选择 PDF、Word、Markdown 或 TXT 文件。';return;}const textFile=files.find(f=>/\.(md|txt)$/i.test(f.name));if(textFile&&textFile.size>1024*1024){d.querySelector('#upload-error').textContent='本原型仅本地读取 1 MB 以内的文本文件。';return;}let text='';if(textFile){try{text=await textFile.text();}catch{d.querySelector('#upload-error').textContent='无法读取这份文本，请重新选择文件。';return;}}const id=d.querySelector('#upload-course').value;openCourse(id);if(text)state.customDocument=text;files.forEach(f=>sources.unshift({id:Date.now()+Math.random(),name:f.name,type:f.name.split('.').pop().toUpperCase(),size:`${(f.size/1024).toFixed(1)} KB`,pages:'本地文件',sample:!text,local:true}));finishUpload();});});}
function finishUpload(){state.sourceBusy=true;state.view='studio';state.tab='content';closeDialog();render();toast('资料已添加到当前原型，正在演示整理过程。');clearTimeout(sourceTimer);sourceTimer=setTimeout(()=>{state.sourceBusy=false;render();toast('资料已就绪，可以检查知识点。');},800);}
function newCourseDialog(){dialog('开始一门新课程','先确定方向，其余内容可以逐步完善。',`<label class="form-field"><span>课程名称</span><input id="new-course-name" placeholder="例如：机器学习基础" maxlength="40" required></label><label class="form-field"><span>面向的学生</span><select id="new-course-audience"><option>本科一年级</option><option>本科二、三年级</option><option>研究生</option><option>通识选修</option></select></label><label class="form-field"><span>你希望学生学会什么？</span><textarea id="new-course-goal" placeholder="用一句话描述课程的核心目标…"></textarea><small>可以先留空，进入课程后再完善。</small></label><p class="form-error" id="course-error"></p>`,`${btn('取消','close-dialog')}${btn('创建课程草稿','confirm-course','primary','arrow')}`,d=>d.querySelector('[data-action="confirm-course"]').addEventListener('click',()=>{const title=d.querySelector('#new-course-name').value.trim();if(!title){d.querySelector('#course-error').textContent='请填写课程名称。';d.querySelector('#new-course-name').focus();return;}const id='course-'+Date.now();courses.push({id,title,code:'NEW COURSE / 04',cover:'ai',desc:d.querySelector('#new-course-audience').value+' · 2026 秋季学期',students:0,chapters:1,complete:0,progress:0,status:'备课中',color:'purple'});courseChapters[id]=['课程导论'];openCourse(id);state.chapter=0;state.customDocument=d.querySelector('#new-course-goal')?.value||'';render();toast('课程草稿已创建，接下来添加教学资料。');}));}
function previewDialog(){if(!questions.length){dialog('学生视角预览','教学内容 · 示例课程',`<div class="document-body" style="padding:0;min-height:0"><p class="document-kicker">${esc(course().title)}</p><h2>${esc(selectedChapter())}</h2><p>在这里，学生会先阅读本节教学内容，再完成老师布置的练习。</p><div class="learning-goal"><strong>学习目标</strong>${esc(concepts[0]?.goal||'理解本节核心概念。')}</div><p>${state.customDocument?esc(state.customDocument).slice(0,1500):'程序可以根据条件选择执行路径，也可以通过循环完成重复工作。请在阅读讲义后，用自己的语言解释代码的运行过程。'}</p></div>`,`${btn('返回备课','close-dialog')}${btn('生成练习后再预览','preview-generate','primary','spark')}`);return;}state.previewAnswers={};const selected=questions.filter(q=>q.selected);if(!selected.length){toast('请至少选入一道题，再打开学生预览。');return;}dialog('学生视角预览','体验学生看到的题目，参考答案默认隐藏。',`<p style="font-size:13px;color:#9da5bb;margin-bottom:14px">${esc(course().title)}　/　${esc(state.assignmentTitle)}</p>${selected.map(q=>`<section class="preview-question"><h3>${q.id}. ${esc(q.title)}</h3>${q.code?`<pre class="code-block">${esc(q.code)}</pre>`:''}${q.options.length?q.options.map((o,i)=>`<label><input type="radio" name="preview-${q.id}" value="${i}" data-preview-question="${q.id}">${String.fromCharCode(65+i)}. ${esc(o)}</label>`).join(''):`<label class="form-field"><textarea placeholder="写下你的解释…" aria-label="第 ${q.id} 题作答"></textarea></label>`}</section>`).join('')}<div id="preview-feedback"></div>`,`<span>预览作答不会计入学生记录</span>${btn('返回修改','close-dialog')}${btn('提交体验','submit-preview','primary','check')}`,d=>{d.querySelectorAll('[data-preview-question]').forEach(input=>input.addEventListener('change',()=>{state.previewAnswers[input.dataset.previewQuestion]=Number(input.value);d.querySelectorAll(`[name="${input.name}"]`).forEach(i=>i.parentElement.classList.toggle('selected',i.checked));}));d.querySelector('[data-action="submit-preview"]').addEventListener('click',()=>{const objective=selected.filter(q=>q.options.length);if(objective.some(q=>state.previewAnswers[q.id]===undefined)){toast('先完成选择题，再提交体验。');return;}const correct=objective.filter(q=>state.previewAnswers[q.id]===q.correct).length;d.querySelector('#preview-feedback').innerHTML=`<div class="preview-result"><strong>已完成本次预览</strong><p>选择题答对 ${correct} / ${objective.length} 道。${selected.some(q=>!q.options.length)?'简答题会进入教师复核。':''}</p>${objective.map(q=>`<p>第 ${q.id} 题：${esc(q.explanation)}</p>`).join('')}</div>`;d.querySelector('#preview-feedback').scrollIntoView({block:'nearest'});});});}
function defaultDue(){const date=new Date(Date.now()+3*86400000);date.setHours(23,59,0,0);return `${date.getFullYear()}-${String(date.getMonth()+1).padStart(2,'0')}-${String(date.getDate()).padStart(2,'0')}T23:59`;}
function publishDialog(){saveInputs();if(state.generateBusy){toast('练习草稿正在生成，请稍候。');return;}if(state.published){successDialog();return;}if(!questions.length){toast('先生成练习，检查后再发布。');state.tab='questions';render();return;}const selected=questions.filter(q=>q.selected);if(!selected.length||selected.length>5){toast('每次作业请选择 1—5 道练习。');state.tab='questions';render();return;}const publishClasses=[...(state.course==='python'?['Python 01 班 · 48 位学生']:state.course==='data'?['数据结构 01 班 · 42 位学生']:[]),...(state.customClass&&state.customClassCourse===state.course?[state.customClass]:[])];if(!publishClasses.length){toast('请先为当前课程创建教学班。');newClassDialog();return;}dialog('检查并布置作业','最后检查一次，学生将看到你确认的内容。',`<div class="publish-summary"><div><span>课程</span><strong>${esc(course().title)}</strong></div><div><span>本次练习</span><strong>${selected.length} 道题 · ${concepts.length} 个知识点</strong></div><div><span>发布状态</span>${badge('等待教师确认','amber')}</div></div><label class="form-field"><span>作业标题</span><input id="publish-title" value="${esc(state.assignmentTitle)}" maxlength="70"></label><label class="form-field"><span>布置给</span><select id="publish-class">${publishClasses.map(name=>`<option>${esc(name)}</option>`).join('')}</select></label><label class="form-field"><span>截止时间</span><input id="publish-due" type="datetime-local" value="${defaultDue()}"></label><label class="publish-check"><input id="publish-confirm" type="checkbox">我已检查题目、参考答案与解析，确认适合当前班级。</label><p class="form-error" id="publish-error"></p>`,`<span>纯前端演示，不会通知真实学生</span>${btn('返回修改','close-dialog')}${btn('确认发布','confirm-publish','primary','send')}`,d=>d.querySelector('[data-action="confirm-publish"]').addEventListener('click',()=>{const title=d.querySelector('#publish-title').value.trim(),due=d.querySelector('#publish-due').value;if(!title){d.querySelector('#publish-error').textContent='请填写作业标题。';return;}if(!due||!Number.isFinite(Date.parse(due))||Date.parse(due)<=Date.now()){d.querySelector('#publish-error').textContent='请选择晚于当前时间的截止时间。';return;}if(!d.querySelector('#publish-confirm').checked){d.querySelector('#publish-error').textContent='请先检查内容，并勾选教师确认。';return;}state.assignmentTitle=title;state.publishClass=d.querySelector('#publish-class').value;state.publishDue=due;state.published=true;publishedHomeworks.unshift({title,course:course().title+' · '+state.publishClass,submitted:0,total:0,status:'进行中',color:'blue',due:due.replace('T',' ')});closeDialog();render();successDialog();}));}
function successDialog(){dialog('发布完成','一次清楚的练习，是下一次理解的开始。',`<div class="success-state"><span class="success-mark">${icon('check')}</span><h3>这一课，准备好了。</h3><p>${esc(state.assignmentTitle)}<br>已在本次原型中标记为发布。</p><div class="success-meta">${esc(state.publishClass||'Python 01 班 · 48 位学生')}<br>${questions.filter(q=>q.selected).length} 道练习　·　截止 ${esc((state.publishDue||'2026-10-30T23:59').replace('T',' '))}<br>演示状态仅保留在当前页面，刷新后恢复。</div></div>`,`${btn('继续备课','close-dialog')}${btn('查看作业','published-assignments','primary','arrow')}`);}
function viewSource(id){const f=sources.find(f=>f.id===Number(id));if(!f)return;dialog(esc(f.name),`${esc(f.type)} · ${esc(f.size)} · ${f.sample?'示例资料':'仅当前会话'}`,`<div class="document-body" style="padding:0;min-height:0"><p class="document-kicker">SOURCE MATERIAL</p><h2>${esc(selectedChapter())}</h2>${f.local&&state.customDocument?`<pre style="font:11px/2 inherit;white-space:pre-wrap;overflow-wrap:anywhere">${esc(state.customDocument)}</pre>`:`<p>条件语句用于决定执行路径。Python 使用 if、elif 和 else 构建分支，使用缩进表示代码块。</p><h3>边界值与循环</h3><p>在检查分数是否及格时，score &gt; 60 与 score &gt;= 60 对恰好等于 60 的情况有不同结果。</p><p>range(start, stop) 包含起点，不包含终点。设计循环时，应先观察实际遍历的值，再推测执行次数。</p><div class="alert-note">这是用于界面演示的资料片段，不是对所选 PDF / Word 的实际解析。</div>`}</div>`,`${btn('关闭','close-dialog')}${btn('用于本节备课','source-to-studio','primary','arrow')}`);}
function editDocument(){dialog('编辑教学内容','修改后的文字会显示在本节教学内容中。',`<label class="form-field"><span>正文内容</span><textarea id="document-edit" style="min-height:310px">${esc(state.customDocument||`程序如何根据不同情况做出选择？又如何把重复的工作交给计算机？\n\n本节学习目标：能写出条件分支与循环，解释每一步的执行过程，并留意边界情况。\n\n01 让程序做出选择\n条件语句让程序根据表达式的真假，决定接下来执行哪一段代码。写条件时，要特别留意等于的情况。\n\n02 把重复交给循环\n当操作需要重复执行，可以使用 for 或 while。先明确循环的起点、结束条件，以及每一轮发生的变化。`)}</textarea></label>`,`${btn('取消','close-dialog')}${btn('保存教学内容','save-document','primary','check')}`);}
function searchDialog(){dialog('搜索工作空间','快速找到课程、教学资料与工作入口。',`<div class="search-dialog"><label class="search-dialog-top">${icon('search')}<input id="global-search" aria-label="搜索工作空间" placeholder="搜索课程或资料…" autofocus></label><div id="global-search-results" class="search-results"></div></div>`,'',d=>{const update=()=>{const term=d.querySelector('#global-search').value.toLowerCase().trim(),matches=[...courses.map(c=>({name:c.title,desc:'课程 · '+c.status,ic:'book',action:'search-course',id:c.id})),...sources.map(f=>({name:f.name,desc:'教学资料 · '+f.type,ic:'file',action:'search-source',id:f.id})),{name:'作业与批改',desc:'工作空间',ic:'edit',action:'search-assignments',id:''}].filter(item=>!term||item.name.toLowerCase().includes(term));d.querySelector('#global-search-results').innerHTML=matches.map(item=>`<button class="search-result" data-action="${item.action}" data-id="${item.id}">${icon(item.ic)}<span>${esc(item.name)}<small>${esc(item.desc)}</small></span></button>`).join('')||'<p class="search-empty">没有找到匹配的内容。</p>';};d.querySelector('#global-search').addEventListener('input',update);update();});}
function settingsDialog(){dialog('工作空间设置','当前为独立的纯前端预览。',`<div class="flex" style="margin-bottom:22px"><span class="avatar">林</span><div><strong style="font-size:15px">林老师</strong><p style="font-size:13px;color:#a4a9bd;margin-top:6px">计算机学院 · 教师工作空间</p></div></div><div class="settings-group"><div>通知提示<p>在原型中显示演示待办提醒</p></div><button class="toggle ${state.notifications?'':'off'}" role="switch" aria-checked="${state.notifications}" aria-label="通知提示" data-action="toggle-notifications"></button></div><div class="settings-group"><div>本次体验数据<p>修改仅保留到页面刷新前</p></div><button class="text-btn" data-action="reset-prototype">恢复初始状态</button></div><p style="font-size:12px;line-height:1.9;color:#a6acbf;margin-top:21px">所有教学记录、学生与课程均为示例。未连接登录、模型、文件上传或发布服务。</p>`,btn('完成','close-dialog'));}
function newClassDialog(){dialog('新建教学班','给同一门课的学生，一个共同的学习空间。',`<label class="form-field"><span>班级名称</span><input id="new-class-name" placeholder="例如：Python 02 班" maxlength="40"></label><label class="form-field"><span>关联课程</span><select id="new-class-course">${courses.map(c=>`<option value="${c.id}" ${c.id===state.course?'selected':''}>${esc(c.title)}</option>`).join('')}</select></label><p class="form-error" id="class-error"></p>`,`${btn('取消','close-dialog')}${btn('创建班级','confirm-class','primary','plus')}`,d=>d.querySelector('[data-action="confirm-class"]').addEventListener('click',()=>{const name=d.querySelector('#new-class-name').value.trim();if(!name){d.querySelector('#class-error').textContent='请填写班级名称。';return;}state.customClass=name;state.customClassCourse=d.querySelector('#new-class-course').value;navigate('classes');toast('演示班级已创建。');}));}

document.addEventListener('click',event=>{const target=event.target.closest('[data-action]');if(!target)return;const a=target.dataset.action;saveInputs();switch(a){
 case 'navigate':navigate(target.dataset.view);break;
 case 'open-course':openCourse(target.dataset.course||'python',target.dataset.tab);break;
 case 'menu':document.querySelector('.sidebar').classList.add('open');document.querySelector('.sidebar-shade').classList.add('open');syncMobileNavigation();break;
 case 'close-menu':document.querySelector('.sidebar').classList.remove('open');document.querySelector('.sidebar-shade').classList.remove('open');syncMobileNavigation();break;
 case 'tab':state.tab=target.dataset.tab;render();break;
 case 'chapter':state.chapter=Number(target.dataset.index);state.tab='content';state.customDocument='';state.published=false;questions=[];render();toast('已切换章节；练习草稿已清空，示例讲义仍用于展示布局。');break;
 case 'step':{const i=Number(target.dataset.index);if(i===3){publishDialog();}else{state.tab=['content','concepts','questions'][i];render();}break;}
 case 'extract':state.tab='concepts';state.chat.push({role:'assistant',text:'已整理好本节的知识点。请检查每一个学习目标，直接修改后再设计练习。'});render();toast('已切换到知识点，可直接编辑学习目标。');break;
 case 'generate':generate();break;
 case 'ai-toggle':state.aiOpen=!state.aiOpen;render();if(state.aiOpen)document.querySelector('#ai-input')?.focus();break;
 case 'ai-prompt':sendAI(target.dataset.prompt);break;
 case 'upload':uploadDialog();break;
 case 'sample-upload':closeDialog();openCourse('python');finishUpload();break;
 case 'new-course':newCourseDialog();break;
 case 'course-filter':state.courseFilter=target.dataset.filter;render();break;
 case 'assignment-filter':state.filter=target.dataset.filter;render();break;
 case 'edit-question':state.questionEditing=Number(target.dataset.id);render();break;
 case 'cancel-edit':state.questionEditing=null;render();break;
 case 'save-question':{const q=questions.find(q=>q.id===Number(target.dataset.id)),value=document.querySelector('#question-title-'+q.id).value.trim();if(!value){toast('题目内容不能为空。');return;}q.title=value;state.questionEditing=null;state.published=false;render();toast('题目修改已保留。');break;}
 case 'preview':previewDialog();break;
 case 'preview-generate':closeDialog();generate();break;
 case 'publish':publishDialog();break;
 case 'published-assignments':navigate('assignments');break;
 case 'view-source':viewSource(target.dataset.id);break;
 case 'source-to-studio':closeDialog();state.tab='content';navigate('studio');break;
 case 'edit-document':editDocument();break;
 case 'save-document':{const val=document.querySelector('#document-edit').value.trim();if(!val){toast('教学内容不能为空。');return;}state.customDocument=val;state.published=false;closeDialog();render();toast('教学内容已保留。');break;}
 case 'document-options':dialog('教学内容操作','将本节内容带到下一步。',`<div class="stack">${btn('编辑教学内容','edit-document','','edit')}${btn('学生视角预览','preview','','eye')}${btn('下载当前课程草稿','export-draft','','download')}</div>`);break;
 case 'export-draft':{const blob=new Blob([JSON.stringify({prototype:true,course:course().title,chapter:selectedChapter(),content:state.customDocument||'示例教学内容',concepts,questions},null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='知行-课程草稿.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);closeDialog();toast('课程草稿已导出为 JSON。');break;}
 case 'course-outline':dialog('课程大纲',esc(course().title),`<div class="stack">${chapterNames().map((name,i)=>`<button class="search-result" data-action="dialog-chapter" data-index="${i}"><span class="badge">${String(i+1).padStart(2,'0')}</span>${esc(name)}</button>`).join('')}</div>`);break;
 case 'dialog-chapter':state.chapter=Number(target.dataset.index);state.tab='content';state.customDocument='';questions=[];state.published=false;closeDialog();render();break;
 case 'review':state.review=Number(target.dataset.index);state.view='assignments';render();document.querySelector('.review-layout')?.scrollIntoView({block:'start',behavior:'smooth'});break;
 case 'next-review':state.review=(state.review+1)%demoSubmissions.length;render();document.querySelector('.review-layout')?.scrollIntoView({block:'start',behavior:'instant'});break;
 case 'save-review':{const val=document.querySelector('#review-feedback').value.trim();if(!val){toast('请先写下给学生的反馈。');document.querySelector('#review-feedback').focus();return;}const notes=document.querySelector('#review-notes').value.trim();if(!notes){toast('请填写复核依据，说明判断理由。');document.querySelector('#review-notes').focus();return;}demoSubmissions[state.review].notes=notes;demoSubmissions[state.review].verdict=document.querySelector('#review-verdict').value;demoSubmissions[state.review].feedback=val;if(!state.reviewed.includes(state.review))state.reviewed.push(state.review);render();document.querySelector('.review-layout')?.scrollIntoView({block:'start',behavior:'instant'});toast('复核反馈已保留在当前原型中。');break;}
 case 'search':searchDialog();break;
 case 'search-course':openCourse(target.dataset.id);break;
 case 'search-source':{const id=target.dataset.id;closeDialog();viewSource(id);break;}
 case 'search-assignments':navigate('assignments');break;
 case 'notifications':dialog('需要你关注','今天的教学动态',`<div class="notification-list"><article class="notification-item"><h3>${Math.max(0,12-state.reviewed.length)} 份作业等待批改</h3><p>Python 01 班的学生已提交本章练习，其中 3 份解释值得重点关注。</p><button class="text-btn" data-action="navigate" data-view="assignments">查看作答 ${icon('arrow')}</button></article><article class="notification-item"><h3>本节教学资料已就绪</h3><p>继续检查知识点，或生成练习草稿。</p><button class="text-btn" data-action="open-course" data-course="python">继续备课 ${icon('arrow')}</button></article></div>`,btn('我知道了','close-dialog'));break;
 case 'help':dialog('一起试试这条备课流程','这是一份可操作的纯前端原型。',`<div class="document-body" style="padding:0;min-height:0"><h3 style="margin-top:0">01　进入课程</h3><p>从工作台打开 Python 程序设计，查看教学内容与参考资料。</p><h3>02　整理和设计</h3><p>切换到知识点，直接编辑教学目标，再点击“设计练习”。右侧助手可体验示例问答。</p><h3>03　检查并发布</h3><p>修改题目，打开学生预览，最后选择班级、截止时间并确认发布。</p><h3>快速找到内容</h3><p>点击右上角搜索框，或按 Ctrl / ⌘ + K，查找课程、资料和工作入口。</p><div class="alert-note">所有状态都在浏览器内存中，刷新后恢复。文件不会上传，AI 不会发起模型请求，作业不会通知真实学生。</div></div>`,`${btn('关闭','close-dialog')}${btn('开始体验','help-start','primary','arrow')}`);break;
 case 'help-start':openCourse('python');break;
 case 'workspace':dialog('教师工作空间','林老师 · 计算机学院',`<p style="font-size:14px;line-height:2;color:#969eb5">这里集中管理课程、教学资料、作业与班级。你可以在左侧导航切换工作区域。</p><div style="margin-top:20px">${badge('纯前端交互原型','blue')}</div>`,`${btn('查看我的课程','navigate','primary','','data-view="courses"')}`);break;
 case 'settings':settingsDialog();break;
 case 'toggle-notifications':state.notifications=!state.notifications;target.classList.toggle('off',!state.notifications);target.setAttribute('aria-checked',String(state.notifications));break;
 case 'reset-prototype':location.reload();break;
 case 'new-class':newClassDialog();break;
 case 'copy-invite':{const text='欢迎加入知行教学班，邀请码：'+target.dataset.invite;if(navigator.clipboard?.writeText){navigator.clipboard.writeText(text).then(()=>toast('班级邀请已复制。')).catch(()=>dialog('班级邀请','选中文字即可复制。',`<textarea style="width:100%;min-height:80px;padding:12px;border:1px solid #dde3f2;border-radius:6px">${esc(text)}</textarea>`,btn('关闭','close-dialog')));}else{dialog('班级邀请','选中文字即可复制。',`<textarea style="width:100%;min-height:80px;padding:12px;border:1px solid #dde3f2;border-radius:6px">${esc(text)}</textarea>`,btn('关闭','close-dialog'));}break;}
 case 'close-dialog':closeDialog();break;
 }});
document.addEventListener('keydown',e=>{if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='k'){e.preventDefault();searchDialog();return;}if(e.key==='Escape'){document.querySelector('.sidebar')?.classList.remove('open');document.querySelector('.sidebar-shade')?.classList.remove('open');syncMobileNavigation();}if(overlay.querySelector('dialog[open]'))return;if(e.ctrlKey||e.metaKey||e.altKey||e.shiftKey||e.target.closest('input,textarea,select,[contenteditable]'))return;});
const initialHash=location.hash.slice(1);if(Object.hasOwn(viewNames,initialHash))state.view=initialHash;
function syncMobileNavigation(){const sidebar=document.querySelector('.sidebar');if(sidebar)sidebar.inert=matchMedia('(max-width: 600px)').matches&&!sidebar.classList.contains('open');}
matchMedia('(max-width: 600px)').addEventListener('change',syncMobileNavigation);
window.addEventListener('hashchange',()=>{const view=location.hash.slice(1);if(Object.hasOwn(viewNames,view)&&view!==state.view){saveInputs();state.view=view;closeDialog();render();window.scrollTo({top:0,behavior:'instant'});}});
render();
